<template><view class="mg-result"><view class="card"><text class="title">{{result?.endReason==='FINISHED'?'训练完成':'训练已结束'}}</text><view v-if="result" class="grid"><view><strong>康复数据</strong><text>本组有效深蹲 {{result.training.left_count}}</text><text>跨组总次数 {{result.training.left_total_count}}</text><text>最大活动幅度 {{Math.round(result.training.max_rom_deg)}}°</text><text>第 {{result.training.set_index}}/{{result.training.target_sets}} 组 · 完成度 {{Math.round(result.training.overall_completion_percent)}}%</text><text>左右对称 {{Math.round(result.training.symmetry_percent)}}%</text><text>有效训练 {{Math.round(result.activeElapsedMs/1000)}}秒</text></view><view><strong>地鼠成绩</strong><text>成功闪避 {{result.game.dodges}}</text><text>被敲中 {{result.game.hits}}</text><text>最大连击 x{{result.game.bestCombo}}</text><text>总分 {{result.game.score}}</text></view></view><view class="actions"><button @click="again">再练一次</button><button class="back" @click="back">返回首页</button></view></view></view></template><script lang="ts">import{consumeMoleResult,getMoleConfig}from'../runtime/session-runtime';import type{MoleTrainingResult}from'../types/result';import{returnToCaller,appendReturnUrl}from'../../game-platform/runtime/navigation';export default{name:'MoleResult',data(){return{result:null as MoleTrainingResult|null}},onLoad(){this.result=consumeMoleResult()},methods:{again(){const debug=getMoleConfig().debugEnabled?'&debug=1':'';uni.redirectTo({url:appendReturnUrl(`/pages-mole-game/prepare/index?${debug.slice(1)}`)})},back(){returnToCaller()}}}</script><style scoped>.mg-result{display:flex;align-items:center;justify-content:center;box-sizing:border-box;width:100vw;min-height:100vh;height:100vh;overflow:auto;padding:12px;background:linear-gradient(145deg,#e7f5d5,#fff2bd);font-family:"Microsoft YaHei",sans-serif;color:#405329}.card{width:min(720px,88vw);max-height:calc(100vh - 24px);overflow:auto;padding:22px;border:4px solid #7ba53e;border-radius:24px;background:#fff}.title{display:block;text-align:center;font-size:38px;font-weight:900;color:#71942e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:15px 0}.grid>view{padding:14px;border-radius:15px;background:#f2f8e7}.grid strong,.grid text{display:block}.grid strong{font-size:20px}.grid text{margin-top:7px}.actions{display:flex;gap:12px}.actions button{flex:1;height:46px;border:0;border-radius:999px;background:#75a63d;color:#fff}.actions .back{background:#eab230;color:#604407}@media(max-height:420px){.mg-result{align-items:flex-start}.card{margin-top:8px;padding:15px}.title{font-size:28px}.grid{gap:8px;margin:9px 0}.grid>view{padding:9px}.grid text{margin-top:4px;font-size:12px}.actions button{height:40px}}</style>
